import{_ as t,o as i,c as s,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Version des Documents et Notes de Maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0099-文档版本与维护说明.md","filePath":"fr/0099-文档版本与维护说明.md"}'),n={name:"fr/0099-文档版本与维护说明.md"};function a(o,e,d,u,l,c){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="version-des-documents-et-notes-de-maintenance" tabindex="-1">Version des Documents et Notes de Maintenance <a class="header-anchor" href="#version-des-documents-et-notes-de-maintenance" aria-label="Permalink to &quot;Version des Documents et Notes de Maintenance&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>99</td></tr><tr><td>Module</td><td>Annexes et matériaux de référence</td></tr><tr><td>Mots-clés principaux</td><td>gestion des versions, notes de maintenance, normes documentaires, journal des mises à jour, maintenance des paramètres</td></tr></tbody></table><h2 id="i-presentation-du-systeme-documentaire" tabindex="-1">I. Présentation du système documentaire <a class="header-anchor" href="#i-presentation-du-systeme-documentaire" aria-label="Permalink to &quot;I. Présentation du système documentaire&quot;">​</a></h2><p>Le système de paramètres de la Civilisation Symbiotique de l&#39;Ancre se compose de 100 documents Markdown, numérotés de 00 à 99, répartis en dix modules majeurs, avec 10 documents par module. Le système documentaire prend SPEC.md (Spécification de génération des documents) comme contrainte stricte, prend « 00-Heng Yuan Zhou : Vue d&#39;ensemble du Cosmos » comme plan général, développe en détail les documents de chaque module sous différents angles, et utilise enfin les documents d&#39;annexes 90-99 pour l&#39;indexation, la synthèse et le classement. L&#39;ensemble du système documentaire constitue une base de connaissances complète, logiquement cohérente, clairement hiérarchisée et mutuellement référencée.</p><p>La conception du système documentaire suit trois grands principes : « modularité, structuration, extensibilité ». La modularité signifie que chaque document se concentre sur un thème spécifique et forme un article indépendant ; la structuration signifie que tous les documents suivent une spécification de format unifiée, facilitant la lecture et la recherche ; l&#39;extensibilité signifie que le système documentaire réserve une ample marge d&#39;expansion, permettant d&#39;améliorer continuellement les paramètres en révisant les documents existants et en ajoutant de nouveaux contenus.</p><h2 id="ii-regles-de-numerotation-des-versions" tabindex="-1">II. Règles de numérotation des versions <a class="header-anchor" href="#ii-regles-de-numerotation-des-versions" aria-label="Permalink to &quot;II. Règles de numérotation des versions&quot;">​</a></h2><p>Le système documentaire adopte une règle de numérotation à trois niveaux « version majeure.version mineure.numéro de révision » :</p><table tabindex="0"><thead><tr><th>Niveau de version</th><th>Règle de numérotation</th><th>Condition de déclenchement</th><th>Exemple</th></tr></thead><tbody><tr><td>Version majeure</td><td>Incrémente à partir de 1</td><td>Ajustement architectural majeur du système documentaire, tel que la redéfinition des modules ou la modification des paramètres fondamentaux</td><td>v1.0 → v2.0</td></tr><tr><td>Version mineure</td><td>Incrémente à partir de 0</td><td>Révision substantielle du contenu fondamental d&#39;un document, ou ajout de contenus de paramètres importants</td><td>v1.0 → v1.1</td></tr><tr><td>Numéro de révision</td><td>Incrémente à partir de 0</td><td>Modifications non substantielles telles que corrections de texte, ajustements de format et unification de la terminologie</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>La version globale actuelle du système documentaire est v1.0, c&#39;est-à-dire la première publication complète. Chaque document enregistre son propre numéro de version dans son bloc d&#39;informations documentaires, et le numéro de version global du système documentaire est enregistré de manière unifiée dans le présent document.</p><h2 id="iii-rappel-des-specifications-de-format-des-documents" tabindex="-1">III. Rappel des spécifications de format des documents <a class="header-anchor" href="#iii-rappel-des-specifications-de-format-des-documents" aria-label="Permalink to &quot;III. Rappel des spécifications de format des documents&quot;">​</a></h2><p>Tous les documents doivent suivre les spécifications de format unifiées suivantes (voir SPEC.md pour les spécifications détaillées) :</p><h3 id="_3-1-nommage-des-fichiers" tabindex="-1">3.1 Nommage des fichiers <a class="header-anchor" href="#_3-1-nommage-des-fichiers" aria-label="Permalink to &quot;3.1 Nommage des fichiers&quot;">​</a></h3><p>Le format du nom de fichier est <code>XX-Titre du document.md</code>, où XX est un numéro à deux chiffres de 00 à 99, et le titre est en chinois sans espaces.</p><h3 id="_3-2-structure-des-documents" tabindex="-1">3.2 Structure des documents <a class="header-anchor" href="#_3-2-structure-des-documents" aria-label="Permalink to &quot;3.2 Structure des documents&quot;">​</a></h3><p>Chaque document doit contenir les éléments structurels suivants :</p><ol><li><strong>Titre de niveau un</strong> : titre du document (conforme au nom du fichier)</li><li><strong>Bloc d&#39;informations du document</strong> : tableau du numéro, du module et des mots-clés essentiels (3 à 5)</li><li><strong>Corps du texte</strong> : au moins 3 sections avec titres de niveau deux, utilisant des éléments structurés tels que listes et tableaux</li><li><strong>Conclusion</strong> : court paragraphe de synthèse</li><li><strong>Documents associés</strong> : liste de 2 à 3 numéros et noms de documents liés</li></ol><h3 id="_3-3-exigence-de-longueur" tabindex="-1">3.3 Exigence de longueur <a class="header-anchor" href="#_3-3-exigence-de-longueur" aria-label="Permalink to &quot;3.3 Exigence de longueur&quot;">​</a></h3><p>Le corps de chaque document ne doit pas être inférieur à 800 caractères (hors titres et méta-informations).</p><h3 id="_3-4-style-de-redaction" tabindex="-1">3.4 Style de rédaction <a class="header-anchor" href="#_3-4-style-de-redaction" aria-label="Permalink to &quot;3.4 Style de rédaction&quot;">​</a></h3><ul><li>Style sérieux et systématique de document de paramètres, comparable à une encyclopédie/recueil de paramètres</li><li>Utilisation de termes unifiés tels que « Univers Hengyuan », « Ancre » et « Symbiose »</li><li>Les nouveaux paramètres ajoutés doivent être logiquement cohérents avec les paramètres existants et conformes au principe de « La réalité comme fondement, l&#39;amélioration par les lois »</li></ul><h2 id="iv-organisation-de-maintenance-et-responsabilites" tabindex="-1">IV. Organisation de maintenance et responsabilités <a class="header-anchor" href="#iv-organisation-de-maintenance-et-responsabilites" aria-label="Permalink to &quot;IV. Organisation de maintenance et responsabilités&quot;">​</a></h2><h3 id="_4-1-comite-de-maintenance-des-parametres" tabindex="-1">4.1 Comité de Maintenance des Paramètres <a class="header-anchor" href="#_4-1-comite-de-maintenance-des-parametres" aria-label="Permalink to &quot;4.1 Comité de Maintenance des Paramètres&quot;">​</a></h3><p>Le Comité de Maintenance des Paramètres est l&#39;organe de maintenance suprême du système documentaire, composé de créateurs de paramètres chevronnés, d&#39;experts en vérification logique et de représentants des utilisateurs. Ses responsabilités essentielles comprennent :</p><ul><li>Examiner l&#39;architecture globale du système documentaire et les plans de révision majeurs</li><li>Vérifier les changements majeurs de paramètres pour garantir la cohérence avec les paramètres fondamentaux</li><li>Arbitrer les litiges de paramètres et fournir des interprétations faisant autorité</li><li>Organiser régulièrement des auto-vérifications complètes de la cohérence des paramètres</li><li>Publier les mises à jour globales de version du système documentaire</li></ul><h3 id="_4-2-mainteneurs-de-modules" tabindex="-1">4.2 Mainteneurs de modules <a class="header-anchor" href="#_4-2-mainteneurs-de-modules" aria-label="Permalink to &quot;4.2 Mainteneurs de modules&quot;">​</a></h3><p>Chaque module désigne un mainteneur de module, chargé de la maintenance quotidienne des 10 documents de ce module. Ses responsabilités comprennent :</p><ul><li>Suivre la cohérence des paramètres des documents du module</li><li>Examiner les demandes de révision des documents du module</li><li>Coordonner les références croisées entre les documents du module</li><li>Recueillir les retours et suggestions des utilisateurs sur le contenu du module</li><li>Rendre compte régulièrement de l&#39;état de maintenance du module au Comité de Maintenance des Paramètres</li></ul><h3 id="_4-3-createurs-de-documents" tabindex="-1">4.3 Créateurs de documents <a class="header-anchor" href="#_4-3-createurs-de-documents" aria-label="Permalink to &quot;4.3 Créateurs de documents&quot;">​</a></h3><p>Tout créateur qualifié peut participer à la création et à la révision des documents. Les responsabilités des créateurs comprennent :</p><ul><li>Créer ou réviser des documents conformément aux spécifications de format</li><li>Garantir que le contenu créé passe l&#39;examen de la Liste d&#39;Auto-Vérification des Contradictions de Paramètres</li><li>Joindre une description détaillée de la révision lors de la soumission</li><li>Coopérer au travail d&#39;examen des mainteneurs et du Comité</li></ul><h2 id="v-processus-de-revision" tabindex="-1">V. Processus de révision <a class="header-anchor" href="#v-processus-de-revision" aria-label="Permalink to &quot;V. Processus de révision&quot;">​</a></h2><h3 id="_5-1-processus-de-revision-regulier" tabindex="-1">5.1 Processus de révision régulier <a class="header-anchor" href="#_5-1-processus-de-revision-regulier" aria-label="Permalink to &quot;5.1 Processus de révision régulier&quot;">​</a></h3><ol><li><strong>Soumettre une demande</strong> : le créateur soumet une demande de révision au mainteneur du module, comprenant le numéro du document à réviser, la description du contenu de la révision et les raisons de la révision.</li><li><strong>Examen du module</strong> : le mainteneur du module examine le contenu de la révision, en s&#39;attachant particulièrement aux spécifications de format et à la cohérence intra-module. Après approbation, il est soumis au Comité de Maintenance des Paramètres.</li><li><strong>Approbation du Comité</strong> : le Comité de Maintenance des Paramètres effectue l&#39;examen final du contenu de la révision, en s&#39;attachant particulièrement à la cohérence inter-modules et à la cohérence des paramètres fondamentaux.</li><li><strong>Exécution de la révision</strong> : après approbation, le mainteneur du module ou l&#39;auteur original exécute la révision du document.</li><li><strong>Mise à jour de version</strong> : après l&#39;achèvement de la révision, mettre à jour le numéro de version du document et l&#39;enregistrer dans le journal des mises à jour du présent document.</li><li><strong>Synchronisation des documents associés</strong> : si le contenu de la révision affecte d&#39;autres documents, les documents associés doivent être révisés en synchronisation.</li></ol><h3 id="_5-2-processus-de-revision-d-urgence" tabindex="-1">5.2 Processus de révision d&#39;urgence <a class="header-anchor" href="#_5-2-processus-de-revision-d-urgence" aria-label="Permalink to &quot;5.2 Processus de révision d&#39;urgence&quot;">​</a></h3><p>Pour les situations d&#39;urgence où de graves contradictions ou erreurs de paramètres sont découvertes, le processus de révision d&#39;urgence peut être déclenché :</p><ol><li><strong>Rapport d&#39;urgence</strong> : le découvreur signale immédiatement le problème au Comité de Maintenance des Paramètres.</li><li><strong>Examen rapide</strong> : le Comité achève l&#39;examen d&#39;urgence dans les 24 heures et fournit un plan de révision.</li><li><strong>Exécution de la révision</strong> : désigner une personne dédiée pour exécuter immédiatement la révision.</li><li><strong>Enregistrement rétroactif</strong> : après l&#39;achèvement de la révision, enregistrer rétroactivement la demande de révision et les dossiers d&#39;examen.</li></ol><h3 id="_5-3-revision-globale-periodique" tabindex="-1">5.3 Révision globale périodique <a class="header-anchor" href="#_5-3-revision-globale-periodique" aria-label="Permalink to &quot;5.3 Révision globale périodique&quot;">​</a></h3><p>Le Comité de Maintenance des Paramètres organise une fois par an une révision globale du système documentaire, comprenant :</p><ul><li>Une auto-vérification complète de la cohérence des paramètres</li><li>Le traitement centralisé des retours des utilisateurs</li><li>L&#39;unification et la mise à jour du système terminologique</li><li>La mise à jour synchronisée des documents d&#39;index</li><li>La vérification et la correction unifiées des formats documentaires</li></ul><h2 id="vi-journal-des-mises-a-jour" tabindex="-1">VI. Journal des mises à jour <a class="header-anchor" href="#vi-journal-des-mises-a-jour" aria-label="Permalink to &quot;VI. Journal des mises à jour&quot;">​</a></h2><h3 id="v1-0-premiere-publication-complete" tabindex="-1">v1.0 (Première publication complète) <a class="header-anchor" href="#v1-0-premiere-publication-complete" aria-label="Permalink to &quot;v1.0 (Première publication complète)&quot;">​</a></h3><ul><li>Achèvement de la création et de la publication des 100 documents</li><li>Établissement de l&#39;architecture complète du système documentaire et des spécifications de format</li><li>Achèvement de la couverture des contenus des dix modules majeurs</li><li>Établissement du système d&#39;indexation des annexes (dictionnaire de terminologie, index des systèmes, index juridique, chronologie, registre des Dix Mille Races, figures et organisations, FAQ, liste d&#39;auto-vérification, suggestions d&#39;extension, notes de version)</li></ul><h3 id="zone-d-enregistrement-des-mises-a-jour-ulterieures" tabindex="-1">Zone d&#39;enregistrement des mises à jour ultérieures <a class="header-anchor" href="#zone-d-enregistrement-des-mises-a-jour-ulterieures" aria-label="Permalink to &quot;Zone d&#39;enregistrement des mises à jour ultérieures&quot;">​</a></h3><p>(Les contenus des mises à jour ultérieures seront ajoutés ici, y compris le numéro de version, la date de publication et le résumé des principaux contenus de la mise à jour)</p><h2 id="vii-specifications-de-citation-et-de-reference-croisee-des-documents" tabindex="-1">VII. Spécifications de citation et de référence croisée des documents <a class="header-anchor" href="#vii-specifications-de-citation-et-de-reference-croisee-des-documents" aria-label="Permalink to &quot;VII. Spécifications de citation et de référence croisée des documents&quot;">​</a></h2><h3 id="_7-1-citations-internes" tabindex="-1">7.1 Citations internes <a class="header-anchor" href="#_7-1-citations-internes" aria-label="Permalink to &quot;7.1 Citations internes&quot;">​</a></h3><p>Les références croisées entre documents utilisent le format « numéro de document-titre du document », par exemple « voir le document 84 « Cadre Général des Protocoles Archéologiques » ». Lors de la citation, il faut s&#39;assurer que le document cité existe bien et que le numéro et le titre sont corrects.</p><h3 id="_7-2-citations-terminologiques" tabindex="-1">7.2 Citations terminologiques <a class="header-anchor" href="#_7-2-citations-terminologiques" aria-label="Permalink to &quot;7.2 Citations terminologiques&quot;">​</a></h3><p>À la première utilisation d&#39;un terme fondamental, la mention « voir l&#39;entrée correspondante du document 90 « Le Dictionnaire de Terminologie » » peut être ajoutée. Lors des utilisations ultérieures du même terme, aucune mention répétée n&#39;est nécessaire.</p><h3 id="_7-3-citations-externes" tabindex="-1">7.3 Citations externes <a class="header-anchor" href="#_7-3-citations-externes" aria-label="Permalink to &quot;7.3 Citations externes&quot;">​</a></h3><p>Si des matériaux réels ou des œuvres de fiction extérieurs au système de paramètres doivent être cités, la source doit être indiquée, et il doit être clairement précisé que cette citation constitue un matériau de référence au titre du principe de « La réalité comme fondement », et ne représente pas l&#39;adoption complète de son contenu par le système de paramètres.</p><h2 id="viii-mecanismes-d-assurance-qualite" tabindex="-1">VIII. Mécanismes d&#39;assurance qualité <a class="header-anchor" href="#viii-mecanismes-d-assurance-qualite" aria-label="Permalink to &quot;VIII. Mécanismes d&#39;assurance qualité&quot;">​</a></h2><h3 id="_8-1-auto-verification-des-contradictions-de-parametres" tabindex="-1">8.1 Auto-vérification des contradictions de paramètres <a class="header-anchor" href="#_8-1-auto-verification-des-contradictions-de-parametres" aria-label="Permalink to &quot;8.1 Auto-vérification des contradictions de paramètres&quot;">​</a></h3><p>Tous les documents nouvellement créés et révisés doivent passer tous les points de contrôle de la Liste d&#39;Auto-Vérification des Contradictions de Paramètres (document 97), comprenant plus de 40 points de contrôle dans trois grandes catégories : cohérence des paramètres fondamentaux, cohérence logique inter-modules et spécifications de format documentaire.</p><h3 id="_8-2-relecture-croisee" tabindex="-1">8.2 Relecture croisée <a class="header-anchor" href="#_8-2-relecture-croisee" aria-label="Permalink to &quot;8.2 Relecture croisée&quot;">​</a></h3><p>Chaque document doit, avant publication officielle, faire l&#39;objet d&#39;une relecture croisée par au moins un autre créateur, en s&#39;attachant particulièrement à la cohérence logique inter-modules et à l&#39;uniformité terminologique.</p><h3 id="_8-3-mecanisme-de-retour-des-utilisateurs" tabindex="-1">8.3 Mécanisme de retour des utilisateurs <a class="header-anchor" href="#_8-3-mecanisme-de-retour-des-utilisateurs" aria-label="Permalink to &quot;8.3 Mécanisme de retour des utilisateurs&quot;">​</a></h3><p>Le système documentaire met en place des canaux de retour utilisateur ; les utilisateurs peuvent soumettre leurs retours par les moyens suivants :</p><ul><li>Signaler des contradictions de paramètres et des erreurs logiques</li><li>Soulever des problèmes d&#39;incohérence terminologique</li><li>Suggérer des compléments ou des révisions de contenus spécifiques</li><li>Signaler des erreurs de format et de texte</li></ul><p>Tous les retours sont traités par catégories par les mainteneurs de modules, et les retours importants sont soumis au Comité de Maintenance des Paramètres pour délibération.</p><h3 id="_8-4-rapport-trimestriel-de-coherence" tabindex="-1">8.4 Rapport trimestriel de cohérence <a class="header-anchor" href="#_8-4-rapport-trimestriel-de-coherence" aria-label="Permalink to &quot;8.4 Rapport trimestriel de cohérence&quot;">​</a></h3><p>Le Comité de Maintenance des Paramètres publie chaque trimestre un « Rapport de Cohérence des Paramètres », dont le contenu comprend :</p><ul><li>Les contradictions de paramètres découvertes au cours du trimestre et leur traitement</li><li>Les statistiques des révisions documentaires du trimestre</li><li>Les progrès de l&#39;unification terminologique</li><li>Le traitement des retours des utilisateurs</li><li>Le plan de maintenance du trimestre suivant</li></ul><h2 id="ix-stockage-et-distribution-des-documents" tabindex="-1">IX. Stockage et distribution des documents <a class="header-anchor" href="#ix-stockage-et-distribution-des-documents" aria-label="Permalink to &quot;IX. Stockage et distribution des documents&quot;">​</a></h2><h3 id="_9-1-format-de-stockage" tabindex="-1">9.1 Format de stockage <a class="header-anchor" href="#_9-1-format-de-stockage" aria-label="Permalink to &quot;9.1 Format de stockage&quot;">​</a></h3><p>Tous les documents sont stockés au format Markdown (.md), garantissant la lisibilité multiplateforme et la commodité de la gestion des versions. Les documents utilisent l&#39;encodage UTF-8, prenant en charge le chinois et les caractères spéciaux.</p><h3 id="_9-2-structure-de-repertoire" tabindex="-1">9.2 Structure de répertoire <a class="header-anchor" href="#_9-2-structure-de-repertoire" aria-label="Permalink to &quot;9.2 Structure de répertoire&quot;">​</a></h3><p>Les documents sont stockés de manière unifiée dans le répertoire <code>anchor-docs/</code>, avec des noms de fichiers au format <code>XX-Titre du document.md</code>. SPEC.md, en tant que fichier de spécification, est également stocké dans le même répertoire.</p><h3 id="_9-3-gestion-des-versions" tabindex="-1">9.3 Gestion des versions <a class="header-anchor" href="#_9-3-gestion-des-versions" aria-label="Permalink to &quot;9.3 Gestion des versions&quot;">​</a></h3><p>Il est recommandé d&#39;utiliser des systèmes de contrôle de version tels que Git pour la gestion des versions des documents, en joignant des messages de commit détaillés enregistrant le contenu et les raisons de chaque révision soumise.</p><h3 id="_9-4-modes-de-distribution" tabindex="-1">9.4 Modes de distribution <a class="header-anchor" href="#_9-4-modes-de-distribution" aria-label="Permalink to &quot;9.4 Modes de distribution&quot;">​</a></h3><p>Le système documentaire peut être distribué des manières suivantes :</p><ul><li>Empaqueté en archive ZIP pour téléchargement</li><li>Déployé en site web statique pour consultation en ligne</li><li>Converti aux formats PDF ou EPUB pour lecture</li><li>Importé dans des systèmes de base de connaissances pour gestion structurée</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La Version des Documents et Notes de Maintenance est la « constitution administrative » du système de paramètres de la Civilisation Symbiotique de l&#39;Ancre. Elle établit les règles de version, l&#39;organisation de maintenance, le processus de révision, les mécanismes d&#39;assurance qualité et les modes de stockage et de distribution du système documentaire, garantissant que ce vaste système de paramètres composé de 100 documents puisse toujours maintenir l&#39;ordre et la cohérence au cours de sa croissance continue. Un bon système de paramètres exige non seulement un contenu exceptionnel, mais aussi un mécanisme de maintenance solide pour assurer son développement sain à long terme. Le présent document est le support essentiel de ce mécanisme.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Liste d&#39;Auto-Vérification des Contradictions de Paramètres)</li><li>90-术语词典 (Le Dictionnaire de Terminologie)</li><li>00-衡元宙宇宙总览 (Heng Yuan Zhou : Vue d&#39;ensemble du Cosmos)</li></ul>',77)])])}const h=t(n,[["render",a]]);export{p as __pageData,h as default};
